        file_to_match = filenames[index - 1]
        for i in range(len(file_to_match)):
            if pattern[i] != '?' and pattern[i] != file_to_match[i]:
                pattern[i] = '?'

    # Check if the constructed pattern matches all files to be deleted
    for index in a_indices:
        if not matches_pattern(filenames[index - 1], ''.join(pattern)):
            return "No"

